import clr
clr.AddReference('RevitAPI')
from Autodesk.Revit.DB import *

category = '{category}'

collector = list(FilteredElementCollector(doc).OfCategory(getattr(BuiltInCategory, 'OST_' + category)).WhereElementIsNotElementType().ToElements())

result = {}
for elem in collector:
    level_param = elem.LookupParameter('Level')
    if level_param:
        level_name = level_param.AsValueString() or 'Без уровня'
    else:
        level_id = elem.LevelId
        if level_id and level_id != ElementId.InvalidElementId:
            level_elem = doc.GetElement(level_id)
            level_name = getattr(level_elem, 'Name', 'Без уровня') if level_elem else 'Без уровня'
        else:
            level_name = 'Без уровня'
    result[level_name] = result.get(level_name, 0) + 1

__result__ = result

import clr
clr.AddReference('RevitAPI')
from Autodesk.Revit.DB import *

category = '{category}'

collector = list(FilteredElementCollector(doc).OfCategory(getattr(BuiltInCategory, 'OST_' + category)).WhereElementIsNotElementType().ToElements())

marks = {}
for elem in collector:
    mark_param = elem.get_Parameter(BuiltInParameter.ALL_MODEL_MARK)
    if mark_param is None:
        continue
    mark_val = mark_param.AsString()
    if not mark_val or mark_val.strip() == '':
        continue
    if mark_val not in marks:
        marks[mark_val] = []
    marks[mark_val].append(elem.Id.IntegerValue)

duplicates = {k: v for k, v in marks.items() if len(v) > 1}

result = []
for mark_val, ids in duplicates.items():
    result.append({'mark': mark_val, 'element_ids': ids, 'count': len(ids)})

result.sort(key=lambda x: x['mark'])
__result__ = result

import clr
clr.AddReference('RevitAPI')
from Autodesk.Revit.DB import *

FT2_TO_M2 = 0.092903

cat_map = {
    'Walls': (BuiltInCategory.OST_Walls, BuiltInParameter.HOST_AREA_COMPUTED),
    'Floors': (BuiltInCategory.OST_Floors, BuiltInParameter.HOST_AREA_COMPUTED),
    'Rooms': (BuiltInCategory.OST_Rooms, BuiltInParameter.ROOM_AREA),
    'Ceilings': (BuiltInCategory.OST_Ceilings, BuiltInParameter.HOST_AREA_COMPUTED)
}

result = {}
for cat_name, (bic, bip) in cat_map.items():
    try:
        elems = list(FilteredElementCollector(doc).OfCategory(bic).WhereElementIsNotElementType().ToElements())
        total = 0.0
        for elem in elems:
            p = elem.get_Parameter(bip)
            if p:
                total += p.AsDouble() * FT2_TO_M2
        result[cat_name] = round(total, 2)
    except Exception:
        result[cat_name] = None

__result__ = result

import clr
clr.AddReference('RevitAPI')
from Autodesk.Revit.DB import *

category = '{category}'
param_name = '{param_name}'
min_val = {min_val}
max_val = {max_val}

collector = list(FilteredElementCollector(doc).OfCategory(getattr(BuiltInCategory, 'OST_' + category)).WhereElementIsNotElementType().ToElements())

out_of_range = []
for elem in collector:
    p = elem.LookupParameter(param_name)
    if p is None:
        continue
    if p.StorageType == StorageType.Double:
        val = p.AsDouble()
    elif p.StorageType == StorageType.Integer:
        val = float(p.AsInteger())
    else:
        continue

    if val < min_val or val > max_val:
        mark_param = elem.get_Parameter(BuiltInParameter.ALL_MODEL_MARK)
        mark = mark_param.AsString() if mark_param else ''
        out_of_range.append({
            'id': elem.Id.IntegerValue,
            'mark': mark,
            'value': round(val, 4)
        })

__result__ = {'count': len(out_of_range), 'elements': out_of_range}

import clr
clr.AddReference('RevitAPI')
from Autodesk.Revit.DB import *

level_name = '{level}'

# Найти Level по имени
levels = list(FilteredElementCollector(doc).OfClass(Level).ToElements())
target_level = None
for lv in levels:
    if getattr(lv, 'Name', '') == level_name:
        target_level = lv
        break

if target_level is None:
    __result__ = {'error': 'Level not found: ' + level_name}
else:
    all_elems = list(FilteredElementCollector(doc).WhereElementIsNotElementType().ToElements())
    cat_counts = {}
    for elem in all_elems:
        lv_param = elem.LookupParameter('Level')
        if lv_param and lv_param.AsValueString() == level_name:
            cat = elem.Category
            if cat is None:
                continue
            cat_name = cat.Name
            cat_counts[cat_name] = cat_counts.get(cat_name, 0) + 1

    sorted_cats = sorted(cat_counts.items(), key=lambda x: x[1], reverse=True)
    __result__ = {
        'level': level_name,
        'total': sum(cat_counts.values()),
        'categories': [{'category': k, 'count': v} for k, v in sorted_cats]
    }
